{"command":"python3 -c '
import os, pty, subprocess

master, slave = pty.openpty()
p = subprocess.Popen(["./executable", "-c", "20", "127.0.0.1"], stdout=slave, stderr=slave, stdin=slave)
os.close(slave)
output = b""
while True:
    try:
        data = os.read(master, 1024)
        if not data:
            break
        output += data
    except OSError:
        break
os.close(master)
p.wait()

for line in output.split(b"\r\n"):
    print(repr(line))
'"}

