{"command":"python3 -c '
import subprocess

def test_timeout(args):
    try:
        p = subprocess.run(["./executable"] + args, capture_output=True, text=True, timeout=2)
        print(f"args: {args}, exit: {p.returncode}, stdout: {p.stdout!r}")
    except subprocess.TimeoutExpired as e:
        print(f"args: {args} TIMED OUT after 2s. Captured stdout:\n{e.stdout!r}")

test_timeout(["-c", "0", "127.0.0.1"])
test_timeout(["-c", "-1", "127.0.0.1"])
'"}

