{"command":"cat << 'EOF' > test_ping.go
package main

import (
	"fmt"
	"net"
	"time"
	"golang.org/x/net/icmp"
	"golang.org/x/net/ipv4"
)

func main() {
	conn, err := net.ListenPacket("udp4", "0.0.0.0:0")
	if err != nil {
		fmt.Println("Listen error:", err)
		return
	}
	defer conn.Close()

	dst, err := net.ResolveUDPAddr("udp4", "127.0.0.1:0")
	if err != nil {
		fmt.Println("Resolve error:", err)
		return
	}

	msg := icmp.Message{
		Type: ipv4.ICMPTypeEcho, Code: 0,
		Body: &icmp.Echo{
			ID: 1, Seq: 0,
			Data: []byte("123456789012345678901234"), // 24 bytes
		},
	}
	wb, err := msg.Marshal(nil)
	if err != nil {
		fmt.Println("Marshal error:", err)
		return
	}

	t0 := time.Now()
	if _, err := conn.WriteTo(wb, dst); err != nil {
		fmt.Println("Write error:", err)
		return
	}

	buf := make([]byte, 1500)
	conn.SetReadDeadline(time.Now().Add(time.Second))
	n, peer, err := conn.ReadFrom(buf)
	rtt := time.Since(t0)
	if err != nil {
		fmt.Println("Read error:", err)
		return
	}
	fmt.Printf("Received %d bytes from %v in %v\n", n, peer, rtt)
}
EOF
go run test_ping.go
rm test_ping.go"}

