{"command":"cat << 'EOF' > test_syscall_ping.go
package main

import (
	"fmt"
	"net"
	"syscall"
	"time"
)

func main() {
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		fmt.Println("Socket error:", err)
		return
	}
	defer syscall.Close(fd)

	sa := &syscall.SockaddrInet4{
		Port: 0,
		Addr: [4]byte{127, 0, 0, 1},
	}

	pkt := []byte{
		8, 0, 0, 0, 0, 1, 0, 0,
		'p', 'i', 'n', 'g', 'u', '-', 'p', 'a', 'y', 'l', 'o', 'a', 'd', '-', 'd', 'a', 't', 'a', '-', '3', '2', 'b', 'y', 't',
	}

	t0 := time.Now()
	if err := syscall.Sendto(fd, pkt, 0, sa); err != nil {
		fmt.Println("Sendto error:", err)
		return
	}

	buf := make([]byte, 1500)
	n, _, err := syscall.Recvfrom(fd, buf, 0)
	rtt := time.Since(t0)
	if err != nil {
		fmt.Println("Recvfrom error:", err)
		return
	}
	fmt.Printf("Received %d bytes in %v\n", n, rtt)
}
EOF
go run test_syscall_ping.go
rm test_syscall_ping.go"}

