func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(
		syscall.SYS_IOCTL,
		fd,
		uintptr(syscall.TCGETS),
		uintptr(unsafe.Pointer(&termios)),
		0, 0, 0,
	)
	return err == 0
}

func shouldColor(fd uintptr) bool {
	if os.Getenv("NO_COLOR") != "" || os.Getenv("TERM") == "dumb" {
		return false
	}
	return isTerminal(fd)
}

func printError(msg string) {
	if shouldColor(os.Stderr.Fd()) {
		fmt.Fprintf(os.Stderr, "[ \x1b[31;1mERROR\x1b[0;22m ] %s\n", msg)
	} else {
		fmt.Fprintf(os.Stderr, "[ ERROR ] %s\n", msg)
	}
}

func printHelp() {
	fmt.Print(`Usage:
  pingu [OPTIONS] HOST

` + "`ping` command but with pingu" + `

Application Options:
  -c, --count=     Stop after <count> replies (default: 20)
  -P, --privilege  Enable privileged mode
  -V, --version    Show version

Help Options:
  -h, --help       Show this help message

`)
}

type options struct {
	count     int
	privilege bool
	version   bool
	help      bool
}

func parseArgs(args []string) (options, []string, int) {
	opts := options{count: 20}
	var posArgs []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-h" || arg == "--help" {
			opts.help = true
			return opts, nil, 0
		}
		if arg == "-V" || arg == "--version" {
			opts.version = true
			return opts, nil, 0
		}
		if arg == "-P" || arg == "--privilege" {
			opts.privilege = true
			continue
		}
		if arg == "-c" || arg == "--count" {
			if i+1 >= len(args) {
				fmt.Fprintln(os.Stderr, "expected argument for flag `-c, --count'")
				printError("parse error: expected argument for flag `-c, --count'")
				return opts, nil, 1
			}
			val, err := strconv.ParseInt(args[i+1], 10, 64)
			if err != nil {
				fmt.Fprintf(os.Stderr, "invalid argument for flag `-c, --count' (expected int): %v\n", err)
				printError(fmt.Sprintf("parse error: invalid argument for flag `-c, --count' (expected int): %v", err))
				return opts, nil, 1
			}
			opts.count = int(val)
			i++
			continue
		}
		if strings.HasPrefix(arg, "--count=") {
			valStr := strings.TrimPrefix(arg, "--count=")
			val, err := strconv.ParseInt(valStr, 10, 64)
			if err != nil {
				fmt.Fprintf(os.Stderr, "invalid argument for flag `-c, --count' (expected int): %v\n", err)
				printError(fmt.Sprintf("parse error: invalid argument for flag `-c, --count' (expected int): %v", err))
				return opts, nil, 1
			}
			opts.count = int(val)
			continue
		}
		if strings.HasPrefix(arg, "-c") && len(arg) > 2 {
			valStr := arg[2:]
			val, err := strconv.ParseInt(valStr, 10, 64)
			if err != nil {
				fmt.Fprintf(os.Stderr, "invalid argument for flag `-c, --count' (expected int): %v\n", err)
				printError(fmt.Sprintf("parse error: invalid argument for flag `-c, --count' (expected int): %v", err))
				return opts, nil, 1
			}
			opts.count = int(val)
			continue
		}
		if strings.HasPrefix(arg, "-") {
			flagName := strings.TrimPrefix(arg, "--")
			if strings.HasPrefix(arg, "-") && !strings.HasPrefix(arg, "--") {
				flagName = arg[1:]
			}
			fmt.Fprintf(os.Stderr, "unknown flag `%s'\n", flagName)
			printError(fmt.Sprintf("parse error: unknown flag `%s'", flagName))
			return opts, nil, 1
		}
		posArgs = append(posArgs, arg)
	}

	return opts, posArgs, -1
}

func renderArtRow(rowStr string, colorEnabled bool) string {
	var sb strings.Builder
	sb.Grow(len(rowStr) * 4)
	for i := 0; i < len(rowStr); i++ {
		ch := rowStr[i]
		switch ch {
		case ' ':
			sb.WriteByte(' ')
		case '.':
			sb.WriteByte('.')
		case 'K':
			if colorEnabled {
				sb.WriteString("\x1b[90;1m#\x1b[0;22m")
			} else {
				sb.WriteByte('#')
			}
		case 'W':
			if colorEnabled {
				sb.WriteString("\x1b[97;1m#\x1b[0;22m")
			} else {
				sb.WriteByte('#')
			}
		case 'Y':
			if colorEnabled {
				sb.WriteString("\x1b[93;1m#\x1b[0;22m")
			} else {
				sb.WriteByte('#')
			}
		case 'R':
			if colorEnabled {
				sb.WriteString("\x1b[91;1m#\x1b[0;22m")
			} else {
				sb.WriteByte('#')
			}
		default:
			sb.WriteByte(ch)
		}
	}
	return sb.String()
}

type stats struct {
	sent int
	recv int
	rtts []time.Duration
}

func (s *stats) print(host string, colorStdout bool) {
	if colorStdout {
		fmt.Printf("\x1b[37;1m\n───────── %s ping statistics ─────────\n\x1b[0m", host)
	} else {
		fmt.Printf("\n───────── %s ping statistics ─────────\n", host)
	}

	var lossStr string
	if s.sent == 0 {
		lossStr = "NaN%"
	} else {
		lossPct := float64(s.sent-s.recv) / float64(s.sent) * 100
		lossStr = fmt.Sprintf("%g%%", lossPct)
	}

	if colorStdout {
		fmt.Printf("\x1b[97;1mPACKET STATISTICS\x1b[0;22m: \x1b[94;1m%d\x1b[0;22m transmitted => \x1b[92;1m%d\x1b[0;22m received (\x1b[91;1m%s\x1b[0;22m loss)\n",
			s.sent, s.recv, lossStr)
	} else {
		fmt.Printf("PACKET STATISTICS: %d transmitted => %d received (%s loss)\n",
			s.sent, s.recv, lossStr)
	}

	var minRtt, avgRtt, maxRtt, stdDevRtt time.Duration
	if len(s.rtts) > 0 {
		minRtt = s.rtts[0]
		maxRtt = s.rtts[0]
		var total time.Duration
		for _, r := range s.rtts {
			if r < minRtt {
				minRtt = r
			}
			if r > maxRtt {
				maxRtt = r
			}
			total += r
		}
		avgRtt = total / time.Duration(len(s.rtts))

		var sumSq float64
		for _, r := range s.rtts {
			diff := float64(r - avgRtt)
			sumSq += diff * diff
		}
		stdDevRtt = time.Duration(math.Sqrt(sumSq / float64(len(s.rtts))))
	}

	if colorStdout {
		fmt.Printf("\x1b[97;1mROUND TRIP\x1b[0;22m: min=\x1b[94;1m%v\x1b[0;22m avg=\x1b[96;1m%v\x1b[0;22m max=\x1b[92;1m%v\x1b[0;22m stddev=\x1b[35;1m%v\x1b[0;22m\n",
			minRtt, avgRtt, maxRtt, stdDevRtt)
	} else {
		fmt.Printf("ROUND TRIP: min=%v avg=%v max=%v stddev=%v\n",
			minRtt, avgRtt, maxRtt, stdDevRtt)
	}
}

func main() {
	opts, posArgs, parseExitCode := parseArgs(os.Args[1:])
	if parseExitCode >= 0 {
		if opts.help {
			printHelp()
			os.Exit(0)
		}
		if opts.version {
			fmt.Printf("pingu: %s\n", version)
			os.Exit(0)
		}
		os.Exit(parseExitCode)
	}

	if len(posArgs) == 0 {
		printError("must requires an argument")
		os.Exit(1)
	}
	if len(posArgs) > 1 {
		printError("too many arguments")
		os.Exit(1)
	}

	host := posArgs[0]

	ipAddr, err := net.ResolveIPAddr("ip", host)
	if err != nil {
		printError(fmt.Sprintf("an error occurred while initializing pinger: failed to init pinger %v", err))
		os.Exit(0)
	}

	isIPv6 := ipAddr.IP.To4() == nil

	colorStdout := shouldColor(os.Stdout.Fd())

	headerStr := fmt.Sprintf("PING %s (%s) type `Ctrl-C` to abort", host, ipAddr.String())
	if colorStdout {
		fmt.Printf("\x1b[97;1m%s\n\x1b[0m", headerStr)
	} else {
		fmt.Println(headerStr)
	}

	if opts.privilege {
		netType := "ip4:icmp"
		if isIPv6 {
			netType = "ip6:ipv6-icmp"
		}
		_, err := net.ListenPacket(netType, "")
		if err != nil {
			printError(fmt.Sprintf("an error occurred when running ping: %v", err))
			os.Exit(2)
		}
	}

	proto := syscall.IPPROTO_ICMP
	domain := syscall.AF_INET
	if isIPv6 {
		proto = syscall.IPPROTO_ICMPV6
		domain = syscall.AF_INET6
	}

	fd, err := syscall.Socket(domain, syscall.SOCK_DGRAM, proto)
	if err != nil {
		printError(fmt.Sprintf("an error occurred when running ping: %v", err))
		os.Exit(2)
	}
	defer syscall.Close(fd)

	tv := syscall.NsecToTimeval(1000 * 1000 * 1000) // 1 second
	syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)

	st := &stats{}

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM, syscall.SIGHUP)

	stopChan := make(chan struct{})

	go func() {
		<-sigChan
		close(stopChan)
	}()

	seq := 0
	count := opts.count

	for {
		select {
		case <-stopChan:
			st.print(host, colorStdout)
			os.Exit(0)
		default:
		}

		if count > 0 && seq >= count {
			st.print(host, colorStdout)
			os.Exit(0)
		}

		var sa syscall.Sockaddr
		if isIPv6 {
			sa6 := &syscall.SockaddrInet6{Port: 0}
			copy(sa6.Addr[:], ipAddr.IP.To16())
			sa = sa6
		} else {
			sa4 := &syscall.SockaddrInet4{Port: 0}
			copy(sa4.Addr[:], ipAddr.IP.To4())
			sa = sa4
		}

		payload := []byte("pingu-payload-data-32bytes-total!!")
		var pkt []byte
		if isIPv6 {
			pkt = make([]byte, 8+24)
			pkt[0] = 128 // ICMPv6 Echo Request
			pkt[1] = 0
			pkt[4] = byte(seq >> 8)
			pkt[5] = byte(seq)
			copy(pkt[8:], payload[:24])
		} else {
			pkt = make([]byte, 8+24)
			pkt[0] = 8 // ICMP Echo Request
			pkt[1] = 0
			pkt[4] = byte(seq >> 8)
			pkt[5] = byte(seq)
			copy(pkt[8:], payload[:24])
		}

		t0 := time.Now()
		st.sent++

		err := syscall.Sendto(fd, pkt, 0, sa)
		if err != nil {
			netName := "udp"
			srcAddr := "0.0.0.0:58" // emulate socket local port / op error format
			dstPort := 0
			if isIPv6 {
				srcAddr = "[::]:0"
			}
			opErr := fmt.Sprintf("write %s %s->%s:%d: sendto: %v", netName, srcAddr, ipAddr.String(), dstPort, err)
			printError(fmt.Sprintf("an error occurred when running ping: %s", opErr))
			st.print(host, colorStdout)
			os.Exit(2)
		}

		buf := make([]byte, 1500)
		n, from, err := syscall.Recvfrom(fd, buf, 0)
		rtt := time.Since(t0)

		if err == nil && n >= 8 {
			st.recv++
			st.rtts = append(st.rtts, rtt)

			ttl := 64
			bytesNum := 32

			artRowStr := asciiArt[seq%20]
			artLine := renderArtRow(artRowStr, colorStdout)

			recvIP := ipAddr.String()
			if from != nil {
				if sa4, ok := from.(*syscall.SockaddrInet4); ok {
					recvIP = net.IP(sa4.Addr[:]).String()
				} else if sa6, ok := from.(*syscall.SockaddrInet6); ok {
					recvIP = net.IP(sa6.Addr[:]).String()
				}
			}

			if colorStdout {
				fmt.Printf("%s seq=\x1b[93;1m%d\x1b[0;22m \x1b[94;1m%d\x1b[0;22mbytes from \x1b[37;1m%s\x1b[0;22m: ttl=\x1b[96;1m%d\x1b[0;22m time=\x1b[95;1m%v\x1b[0;22m\n",
					artLine, seq, bytesNum, recvIP, ttl, rtt)
			} else {
				fmt.Printf("%s seq=%d %dbytes from %s: ttl=%d time=%v\n",
					artLine, seq, bytesNum, recvIP, ttl, rtt)
			}
		}

		seq++

		elapsed := time.Since(t0)
		if elapsed < time.Second {
			select {
			case <-stopChan:
				st.print(host, colorStdout)
				os.Exit(0)
			case <-time.After(time.Second - elapsed):
			}
		}
	}
}
